<?php
declare(strict_types=1);namespace Atlas\Platform\Resources\Authoring;use Atlas\Platform\Core\Audit\AuditRecorder;use RuntimeException;final class WordPressResourceDraftRepository implements ResourceDraftRepository{public function __construct(private object$db,private AuditRecorder$audit){}public function create(string$key,string$fingerprint,array$d,int$userId):array{$ops=$this->db->prefix.'atlas_resource_draft_operations';$existing=$this->db->get_row($this->db->prepare("SELECT fingerprint, resource_id, resource_version_id FROM `{$ops}` WHERE operation_key=%s",$key),ARRAY_A);if(is_array($existing)){if(!hash_equals((string)$existing['fingerprint'],$fingerprint)){throw new RuntimeException('The idempotency key was already used for a different request.');}return['resource_id'=>$existing['resource_id'],'resource_version_id'=>$existing['resource_version_id'],'status'=>'draft','replayed'=>true];}$resource=wp_generate_uuid_4();$version=wp_generate_uuid_4();$source=wp_generate_uuid_4();$citation=wp_generate_uuid_4();$now=current_time('mysql',true);$sourceChecksum=hash('sha256',wp_json_encode($d['source']));$citationKey=hash('sha256',wp_json_encode([$version,$sourceChecksum,$d['citation']]));$this->query('START TRANSACTION');try{$this->insert($this->db->prefix.'atlas_resources',['id'=>$resource,'scope'=>$d['scope'],'scope_key'=>$d['scope_key'],'organization_id'=>$d['organization_id'],'resource_type'=>$d['resource_type'],'slug'=>$d['slug'],'current_version_id'=>null,'created_at'=>$now,'updated_at'=>$now]);$this->insert($this->db->prefix.'atlas_resource_versions',['id'=>$version,'resource_id'=>$resource,'version_number'=>1,'title'=>$d['title'],'summary'=>$d['summary'],'body_json'=>wp_json_encode($d['body']),'review_status'=>'draft','effective_date'=>null,'review_due_date'=>null,'change_summary'=>$d['change_summary'],'author_user_id'=>$userId,'created_at'=>$now]);$sourceId=$this->source($source,$sourceChecksum,$d['source'],$now);$this->insert($this->db->prefix.'atlas_citations',['id'=>$citation,'citation_key'=>$citationKey,'resource_version_id'=>$version,'source_id'=>$sourceId,'page_reference'=>$d['citation']['page']?:null,'section_reference'=>$d['citation']['section']?:null,'display_order'=>0,'created_at'=>$now]);$this->insert($ops,['operation_key'=>$key,'fingerprint'=>$fingerprint,'resource_id'=>$resource,'resource_version_id'=>$version,'created_at'=>$now]);$this->audit->record('resource.draft_created','resources',$userId,$d['organization_id'],'resource',$resource,['resource_version_id'=>$version,'scope'=>$d['scope']]);$this->query('COMMIT');}catch(\Throwable$failure){$this->query('ROLLBACK');throw$failure;}return['resource_id'=>$resource,'resource_version_id'=>$version,'status'=>'draft','replayed'=>false];}private function source(string$id,string$checksum,array$source,string$now):string{$table=$this->db->prefix.'atlas_sources';$existing=$this->db->get_var($this->db->prepare("SELECT id FROM `{$table}` WHERE checksum=%s",$checksum));if(is_string($existing)&&$existing!==''){return$existing;}$this->insert($table,['id'=>$id,'publisher'=>$source['publisher'],'title'=>$source['title'],'source_url'=>$source['url']?:null,'document_identifier'=>$source['document_identifier']?:null,'effective_date'=>$source['effective_date']?:null,'retrieved_at'=>$now,'checksum'=>$checksum,'created_at'=>$now]);return$id;}private function insert(string$table,array$data):void{if($this->db->insert($table,$data)===false){throw new RuntimeException('Resource draft could not be persisted.');}}private function query(string$sql):void{if($this->db->query($sql)===false){throw new RuntimeException('Resource draft transaction failed.');}}}
